def choose_move(observation):
    # Defensive handling of observation with safe defaults
    x = observation.get('player_x', 0) if isinstance(observation, dict) else 0
    y = observation.get('player_y', 0) if isinstance(observation, dict) else 0
    # Look for nearby resources/enemies/territory hints with safe defaults
    positive = observation.get('resources', []) if isinstance(observation, dict) else []
    enemies = observation.get('enemies', []) if isinstance(observation, dict) else []
    allies = observation.get('allies', []) if isinstance(observation, dict) else []
    terrain = observation.get('terrain', {}) if isinstance(observation, dict) else {}

    # Simple robust policy: prefer staying in place unless there is something clearly action-worthy.
    # If there is a nearby resource within 1 step, move toward it.
    if isinstance(positive, (list, tuple)):
        for r in positive:
            if isinstance(r, dict):
                rx = r.get('x', None)
                ry = r.get('y', None)
                if rx is None or ry is None:
                    continue
                if abs(rx - x) <= 1 and abs(ry - y) <= 1:
                    dx = int((rx - x))
                    dy = int((ry - y))
                    # Normalize to -1, 0, 1
                    if dx != 0:
                        dx = int(dx / abs(dx))
                    if dy != 0:
                        dy = int(dy / abs(dy))
                    if dx == 0 and dy == 0:
                        dy = 0
                    return [dx, dy]

    # If there are enemies nearby, try to move away from the closest one within range
    if isinstance(enemies, (list, tuple)):
        best_dx = 0
        best_dy = 0
        min_dist = None
        for e in enemies:
            if not isinstance(e, dict):
                continue
            ex = e.get('x', None)
            ey = e.get('y', None)
            if ex is None or ey is None:
                continue
            dist = max(abs(ex - x), abs(ey - y))
            if min_dist is None or dist < min_dist:
                min_dist = dist
                best_dx = int(x - ex)
                best_dy = int(y - ey)
                if best_dx != 0:
                    best_dx = int(best_dx / abs(best_dx))
                if best_dy != 0:
                    best_dy = int(best_dy / abs(best_dy))
        if min_dist is not None and min_dist <= 1:
            # Threat is adjacent; move away
            return [best_dx, best_dy]

    # Otherwise, try to move toward the center of the map if known
    width = terrain.get('width', 0) if isinstance(terrain, dict) else 0
    height = terrain.get('height', 0) if isinstance(terrain, dict) else 0
    if width and height:
        center_x = int(width / 2)
        center_y = int(height / 2)
        dx = int(center_x - x)
        dy = int(center_y - y)
        if dx != 0:
            dx = int(dx / abs(dx))
        if dy != 0:
            dy = int(dy / abs(dy))
        return [dx, dy]

    # Fallback: stay in place
    return [0, 0]

